class User {           // entity: identity matters
    private String id;
    private String name;

    User(String id, String name) {
        this.id = id;
        this.name = name;
    }
}

class Money {           // value object: defined by its amount
    private long amount;
    private String currency;

    Money(long amount, String currency) {
        this.amount = amount;
        this.currency = currency;
    }

    boolean equalsValue(Money other) {
        return amount == other.amount && currency.equals(other.currency);
    }
}

public class Main {
    public static void main(String[] args) {
        User alice = new User("U-1", "Alice");
        User bob = new User("U-2", "Alice");   // same name, different identity

        Money price1 = new Money(10000, "INR");
        Money price2 = new Money(10000, "INR");   // same value, considered equal

        System.out.println("Alice id: " + alice.id + ", Bob id: " + bob.id + " (different identities, same name)");
        System.out.println("price1 equals price2 by value: " + price1.equalsValue(price2));
    }
}

