#include <iostream>
#include <string>

class User {   // entity: identity matters
public:
    std::string id;
    std::string name;
    User(std::string id, std::string name) : id(id), name(name) {}
};

class Money {   // value object: defined by its amount
public:
    long amount;
    std::string currency;
    Money(long amount, std::string currency) : amount(amount), currency(currency) {}

    bool equalsValue(const Money& other) const {
        return amount == other.amount && currency == other.currency;
    }
};

int main() {
    User alice("U-1", "Alice");
    User bob("U-2", "Alice");   // same name, different identity

    Money price1(10000, "INR");
    Money price2(10000, "INR");   // same value, considered equal

    std::cout << "Alice id: " << alice.id << ", Bob id: " << bob.id << " (different identities, same name)" << std::endl;
    std::cout << "price1 equals price2 by value: " << price1.equalsValue(price2) << std::endl;

    return 0;
}

