from enum import Enum


class VehicleType(Enum):
    BIKE = "BIKE"
    CAR = "CAR"
    TRUCK = "TRUCK"


class Vehicle:
    def __init__(self, number_plate, vehicle_type):
        self._number_plate = number_plate
        self._type = vehicle_type   # car, bike, truck

    def get_number_plate(self):
        return self._number_plate

    def get_type(self):
        return self._type


class Slot:
    def __init__(self, slot_number, allowed_type):
        self._slot_number = slot_number
        self._is_free = True
        self._allowed_type = allowed_type

    def get_slot_number(self):
        return self._slot_number

    def is_free(self):
        return self._is_free

    def get_allowed_type(self):
        return self._allowed_type


if __name__ == "__main__":
    vehicle = Vehicle("KA-01-HH-1234", VehicleType.CAR)
    slot = Slot(12, VehicleType.CAR)

    print(f"Vehicle plate: {vehicle.get_number_plate()}, type: {vehicle.get_type().value}")
    print(f"Slot {slot.get_slot_number()} allowed type: {slot.get_allowed_type().value}, free: {slot.is_free()}")

