#include <iostream>
#include <string>

enum class VehicleType { BIKE, CAR, TRUCK };

std::string vehicleTypeToString(VehicleType type) {
    switch (type) {
        case VehicleType::BIKE: return "BIKE";
        case VehicleType::CAR: return "CAR";
        case VehicleType::TRUCK: return "TRUCK";
    }
    return "UNKNOWN";
}

class Vehicle {
private:
    std::string numberPlate;
    VehicleType type;   // car, bike, truck

public:
    Vehicle(std::string numberPlate, VehicleType type) : numberPlate(numberPlate), type(type) {}

    std::string getNumberPlate() const { return numberPlate; }
    VehicleType getType() const { return type; }
};

class Slot {
private:
    int slotNumber;
    bool isFree;
    VehicleType allowedType;

public:
    Slot(int slotNumber, VehicleType allowedType) : slotNumber(slotNumber), isFree(true), allowedType(allowedType) {}

    int getSlotNumber() const { return slotNumber; }
    bool getIsFree() const { return isFree; }
    VehicleType getAllowedType() const { return allowedType; }
};

int main() {
    Vehicle vehicle("KA-01-HH-1234", VehicleType::CAR);
    Slot slot(12, VehicleType::CAR);

    std::cout << "Vehicle plate: " << vehicle.getNumberPlate() << ", type: " << vehicleTypeToString(vehicle.getType()) << std::endl;
    std::cout << "Slot " << slot.getSlotNumber() << " allowed type: " << vehicleTypeToString(slot.getAllowedType()) << ", free: " << slot.getIsFree() << std::endl;

    return 0;
}

