#include <iostream>
#include <chrono>

class Ticket {
private:
    long long entryTime;   // epoch milliseconds

public:
    Ticket(long long entryTime) : entryTime(entryTime) {}

    long long durationInHours() const {
        long long now = std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
        return (now - entryTime) / (1000 * 60 * 60);
    }
};

int main() {
    long long now = std::chrono::duration_cast<std::chrono::milliseconds>(
        std::chrono::system_clock::now().time_since_epoch()).count();
    long long twoHoursAgo = now - (2LL * 60 * 60 * 1000);

    Ticket ticket(twoHoursAgo);
    std::cout << "Ticket has been active for about " << ticket.durationInHours() << " hour(s)" << std::endl;

    return 0;
}

