import java.util.ArrayList;
import java.util.List;

class Loan {
    BookCopy copy;
    Member member;
    long dueDate;

    Loan(BookCopy copy, Member member, long dueDate) {
        this.copy = copy;
        this.member = member;
        this.dueDate = dueDate;
    }
}

class Member {
    String id;
    String name;
    List<Loan> loans = new ArrayList<>();

    Member(String id, String name) {
        this.id = id;
        this.name = name;
    }
}

class Book {
    String isbn;
    String title;

    Book(String isbn, String title) {
        this.isbn = isbn;
        this.title = title;
    }
}

class BookCopy {
    String copyId;
    Book book;
    boolean available = true;

    BookCopy(String copyId, Book book) {
        this.copyId = copyId;
        this.book = book;
    }
}

public class Main {
    public static void main(String[] args) {
        Book book = new Book("978-0132350884", "Clean Code");
        BookCopy copy = new BookCopy("C-1", book);
        Member member = new Member("M-1", "Priya");

        copy.available = false;
        Loan loan = new Loan(copy, member, System.currentTimeMillis() + 14L * 24 * 60 * 60 * 1000);
        member.loans.add(loan);

        System.out.println(member.name + " borrowed \"" + loan.copy.book.title + "\" (copy " + loan.copy.copyId + ")");
        System.out.println("Copy available: " + copy.available);
        System.out.println(member.name + " has " + member.loans.size() + " active loan(s)");
    }
}

