#include <iostream>
#include <string>
#include <vector>
#include <memory>

class Book {
public:
    std::string isbn;
    std::string title;
    Book(std::string isbn, std::string title) : isbn(isbn), title(title) {}
};

class BookCopy {
public:
    std::string copyId;
    std::shared_ptr<Book> book;
    bool available;
    BookCopy(std::string copyId, std::shared_ptr<Book> book) : copyId(copyId), book(book), available(true) {}
};

class Loan; // forward declaration

class Member {
public:
    std::string id;
    std::string name;
    std::vector<std::shared_ptr<Loan>> loans;
    Member(std::string id, std::string name) : id(id), name(name) {}
};

class Loan {
public:
    std::shared_ptr<BookCopy> copy;
    std::shared_ptr<Member> member;
    long long dueDate;
    Loan(std::shared_ptr<BookCopy> copy, std::shared_ptr<Member> member, long long dueDate)
        : copy(copy), member(member), dueDate(dueDate) {}
};

int main() {
    auto book = std::make_shared<Book>("978-0132350884", "Clean Code");
    auto copy = std::make_shared<BookCopy>("C-1", book);
    auto member = std::make_shared<Member>("M-1", "Priya");

    copy->available = false;
    auto loan = std::make_shared<Loan>(copy, member, 1000000LL);
    member->loans.push_back(loan);

    std::cout << member->name << " borrowed \"" << loan->copy->book->title << "\" (copy " << loan->copy->copyId << ")" << std::endl;
    std::cout << "Copy available: " << copy->available << std::endl;
    std::cout << member->name << " has " << member->loans.size() << " active loan(s)" << std::endl;

    return 0;
}
